from datetime import datetime, timedelta, timezone

from lib.ddb import Ddb
from lib.db import db

class MessageGroups:
  def run(cognito_user_id):
    model = {
      'errors': None,
      'data': None
    }

    sql = db.template('activities/users','uuid_from_cognito_user_id')
    my_user_uuid = db.query_value(sql,{
      'cognito_user_id': cognito_user_id
    })

    print(f"UUID: {my_user_uuid}")

    ddb = Ddb.client()
    data = Ddb.list_message_groups(ddb, my_user_uuid)
    print("list_message_groups:",data)

    # DynamoDB message-group items carry handle and display name but not the
    # Cognito id the frontend needs to build an avatar URL. Enrich at read
    # time with ONE Postgres query for every handle on the page, instead of
    # changing the DynamoDB item shape (which would need a backfill of every
    # existing item). A handle with no match gets None and the frontend
    # falls back to an initial.
    handles = list({group['handle'] for group in data})
    ids_by_handle = {}
    if handles:
      sql = db.template('users','cognito_ids_by_handles')
      rows = db.query_array_json(sql, {'handles': handles}) or []
      ids_by_handle = {row['handle']: row['cognito_user_id'] for row in rows}
    for group in data:
      group['cognito_user_id'] = ids_by_handle.get(group['handle'])

    model['data'] = data
    return model

import './ProfileAvatar.css';
import { useState } from 'react';

export default function ProfileAvatar({ id, name }) {
  // Fall back to an initial when there is no id to build a URL from, or
  // when the image fails to load because the user never uploaded one.
  const [failed, setFailed] = useState(false);
  const initial = (name || '?').trim().charAt(0).toUpperCase() || '?';

  if (!id || failed) {
    return (
      <div className='profile-avatar'>
        <div className='avatar-fallback' aria-label='User avatar'>{initial}</div>
      </div>
    );
  }

  return (
    <div className='profile-avatar'>
      <img
        src={`https://assets.fentoncruddur.com/avatars/processed/${id}.jpg?v=${Date.now()}`}
        className='avatar-img'
        alt='User avatar'
        onError={() => setFailed(true)}
      />
    </div>
  );
}

/* ---- Fallback when there is no uploaded avatar: a circle with an initial ---- */

/* :has() limits this to the fallback case, so existing avatars are untouched. */
.profile-avatar:has(.avatar-fallback) {
  width: 100%;
  height: 100%;
}

.profile-avatar .avatar-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgb(149,0,255);
  color: #fff;
  font-weight: 800;
  font-size: 20px;
  user-select: none;
}

import './MessageGroupItem.css';
import { Link } from "react-router-dom";
import { timeAgo } from '../lib/DateTimeFormats';
import { useParams } from 'react-router-dom';
import ProfileAvatar from './ProfileAvatar';

export default function MessageGroupItem(props) {
  const params = useParams();


  const classes = () => {
    let classes = ["message_group_item"];
    if (params.message_group_uuid == props.message_group.uuid){
      classes.push('active')
    }
    return classes.join(' ');
  }

  return (
    <Link className={classes()} to={`/messages/`+props.message_group.uuid}>
      <div className='message_group_avatar'>
        <ProfileAvatar
          id={props.message_group.cognito_user_id}
          name={props.message_group.display_name}
        />
      </div>
      <div className='message_content'>
        <div className='message_group_meta'>
          <div className='message_group_identity'>
            <div className='display_name'>{props.message_group.display_name}</div>
            <div className="handle">@{props.message_group.handle}</div>
          </div>{/* activity_identity */}
        </div>{/* message_meta */}
        <div className="message">{props.message_group.message}</div>
        <div className="created_at" title={props.message_group.created_at}>
          <span className='ago'>{timeAgo(props.message_group.created_at)}</span> 
        </div>{/* created_at */}
      </div>{/* message_content */}
    </Link>
  );
}

/* ---- Real avatars in the message-group list ---- */

/* Clip the avatar to the existing 50px purple circle. */
.message_group_item .message_group_avatar {
  overflow: hidden;
}

.message_group_item .message_group_avatar .profile-avatar,
.message_group_item .message_group_avatar .avatar-img {
  width: 100%;
  height: 100%;
}

.message_group_item .message_group_avatar .avatar-img {
  display: block;
  border-radius: 999px;
  object-fit: cover;
}
